public class Main {
    public static void main(String[] args) {
        try {
            dangerousTask();
        } catch (InterruptedException e) {
            System.out.println("Caught!");
        }
    }

    // throws: "난 이거 처리 못해, 네가 해!"
    static void dangerousTask() throws InterruptedException {
        System.out.println("Task Start");
        try {
            Thread.sleep(1000);
            throw new InterruptedException(); // Force Error
        } finally {
            System.out.println("Cleanup");
        }
    }
}
